import 'package:flutter/material.dart'; import 'api.dart'; import 'models.dart'; import 'storage.dart'; import 'theme.dart'; import 'screens/marketplace_screen.dart'; import 'screens/login_screen.dart'; import 'screens/workspace_screen.dart'; import 'screens/government_screen.dart';
void main()=>runApp(const RahnumaApp());
class RahnumaApp extends StatefulWidget {const RahnumaApp({super.key});@override State<RahnumaApp> createState()=>_RahnumaAppState();}
class _RahnumaAppState extends State<RahnumaApp>{final store=LocalStore();late final Api api=Api(store);SessionUser? user;bool booting=true;@override void initState(){super.initState();boot();}Future<void>boot()async{final t=await store.token();if(t!=null){try{final d=await api.get('/me');user=SessionUser.fromJson(Map<String,dynamic>.from(d));}catch(_){await store.saveToken(null);}}if(mounted)setState(()=>booting=false);}void logged(SessionUser u){setState(()=>user=u);}Future<void>logout()async{await api.logout();if(mounted)setState(()=>user=null);}void showLogin(BuildContext context){Navigator.push(context,MaterialPageRoute(builder:(_)=>LoginScreen(api:api,onLoggedIn:(u){logged(u);Navigator.pop(context);})));}@override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Rahnuma',theme:RahnumaTheme.light(),home:booting?const Scaffold(body:Center(child:CircularProgressIndicator())):user==null?Builder(builder:(c)=>MarketplaceScreen(api:api,store:store,onLogin:()=>showLogin(c))):user!.isGovernment?GovernmentScreen(api:api,user:user!,onLogout:logout):user!.agencyId!=null?WorkspaceScreen(api:api,store:store,user:user!,onLogout:logout):Scaffold(appBar:AppBar(title:const Text('Rahnuma')),body:Center(child:Text('Role ${user!.role} uses the web administration portal.'))));}
